"""Minimal RESP2 client + redis-server lifecycle helpers for the RDB probe."""
import os
import shutil
import signal
import socket
import subprocess
import time

REDIS_SERVER = "/app/src/redis-server"


class RespError(Exception):
    pass


class Client:
    def __init__(self, host="127.0.0.1", port=6379, timeout=10.0):
        self.sock = socket.create_connection((host, port), timeout=timeout)
        self.buf = b""

    def _readline(self):
        while b"\r\n" not in self.buf:
            chunk = self.sock.recv(65536)
            if not chunk:
                raise RespError("connection closed")
            self.buf += chunk
        line, self.buf = self.buf.split(b"\r\n", 1)
        return line

    def _readexact(self, n):
        while len(self.buf) < n:
            chunk = self.sock.recv(65536)
            if not chunk:
                raise RespError("connection closed")
            self.buf += chunk
        data, self.buf = self.buf[:n], self.buf[n:]
        return data

    def _parse(self):
        line = self._readline()
        tag, rest = line[:1], line[1:]
        if tag == b"+":
            return rest.decode("utf-8", "surrogateescape")
        if tag == b"-":
            raise RespError(rest.decode("utf-8", "surrogateescape"))
        if tag == b":":
            return int(rest)
        if tag == b"$":
            n = int(rest)
            if n == -1:
                return None
            data = self._readexact(n + 2)[:-2]
            return data.decode("utf-8", "surrogateescape")
        if tag == b"*":
            n = int(rest)
            if n == -1:
                return None
            return [self._parse() for _ in range(n)]
        raise RespError("bad RESP tag %r in %r" % (tag, line))

    def cmd(self, *args):
        out = [b"*%d\r\n" % len(args)]
        for a in args:
            b = a.encode("utf-8") if isinstance(a, str) else (
                str(a).encode("utf-8") if not isinstance(a, bytes) else a)
            out.append(b"$%d\r\n" % len(b) + b + b"\r\n")
        self.sock.sendall(b"".join(out))
        return self._parse()

    def close(self):
        try:
            self.sock.close()
        except OSError:
            pass

