            chunk = self.sock.recv(65536)
            if not chunk:
                raise RespError("connection closed")
            self.buf += chunk
        data, self.buf = self.buf[:n], self.buf[n:]
        return data

    def _parse(self):
        line = self._readline()
        tag, rest = line[:1], line[1:]
        if tag == b"+":
            return rest.decode("utf-8", "surrogateescape")
        if tag == b"-":
            raise RespError(rest.decode("utf-8", "surrogateescape"))
        if tag == b":":
            return int(rest)
        if tag == b"$":
            n = int(rest)
            if n == -1:
                return None
            data = self._readexact(n + 2)[:-2]
            return data.decode("utf-8", "surrogateescape")
        if tag == b"*":
            n = int(rest)
            if n == -1:
                return None
            return [self._parse() for _ in range(n)]
        raise RespError("bad RESP tag %r in %r" % (tag, line))

    def cmd(self, *args):
        out = [b"*%d\r\n" % len(args)]
        for a in args:
            b = a.encode("utf-8") if isinstance(a, str) else (
                str(a).encode("utf-8") if not isinstance(a, bytes) else a)
            out.append(b"$%d\r\n" % len(b) + b + b"\r\n")
        self.sock.sendall(b"".join(out))
        return self._parse()

    def close(self):
        try:
            self.sock.close()
        except OSError:
            pass


def prepare_dir(workdir, rdb_src):
    """Private working dir holding only a copy of the one RDB file."""
    if os.path.exists(workdir):
        shutil.rmtree(workdir)
    os.makedirs(workdir)
    dest = os.path.join(workdir, os.path.basename(rdb_src))
    shutil.copyfile(rdb_src, dest)
    return dest


def start_server(workdir, dbfilename, port, extra=()):
    """Start redis-server loading dbfilename from workdir; return (proc, Client)."""
    logpath = os.path.join(workdir, "server.log")
    args = [
        REDIS_SERVER,
        "--dir", workdir,
        "--dbfilename", dbfilename,
        "--port", str(port),
        "--bind", "127.0.0.1",
        "--save", "",             # never rewrite the RDB copy
        "--daemonize", "no",
        "--logfile", logpath,
    ]
    args += [str(a) for a in extra]
    proc = subprocess.Popen(args, stdout=subprocess.DEVNULL,
                            stderr=subprocess.STDOUT)
    deadline = time.time() + 30
    while time.time() < deadline:
        if proc.poll() is not None:
            log = ""
            if os.path.exists(logpath):
                with open(logpath) as fh:
                    log = fh.read()
            raise RespError("redis-server exited rc=%s\n%s" % (proc.returncode, log))
        try:
            c = Client(port=port)
            if c.cmd("PING") == "PONG":
                return proc, c
            c.close()
        except (OSError, RespError):
            time.sleep(0.05)
    proc.kill()
    raise RespError("server on port %d did not become ready" % port)


def stop_server(proc, client):
    """Shut down without persisting, so the RDB copy stays byte-identical."""
    try:
        client.cmd("SHUTDOWN", "NOSAVE")
    except (RespError, OSError):
        pass
    client.close()
    try:
        proc.wait(timeout=15)
    except subprocess.TimeoutExpired:
        proc.send_signal(signal.SIGKILL)
        proc.wait(timeout=10)

